export function buildTodayViewModel({date,availableMinutes=0,plan=null,priorities=[],pastPlans=[]}={}){
  const minutes=value=>Math.max(0,Math.round(Number(value)||0));
  const items=plan?.items||[];
  const plannedMinutes=items.filter(i=>!['skipped','replaced','deferred'].includes(i.status)).reduce((sum,i)=>sum+minutes(i.plannedMinutes),0);
  const executedMinutes=Math.round(items.reduce((sum,i)=>sum+Math.max(0,Number(i.executedSeconds)||0)/60,0));
  const recoveryMinutes=pastPlans.filter(row=>row.date<date).flatMap(row=>row.items||[]).filter(i=>!['completed','skipped','replaced','deferred'].includes(i.status)).reduce((sum,i)=>sum+Math.max(0,minutes(i.plannedMinutes)-Math.round((Number(i.executedSeconds)||0)/60)),0);
  return {date,availableMinutes:minutes(availableMinutes),plannedMinutes,executedMinutes,recoveryMinutes,progress:plannedMinutes?Math.min(100,Math.round(executedMinutes/plannedMinutes*100)):null,
    nextActivity:items.find(i=>!['completed','skipped','replaced','deferred'].includes(i.status))||priorities[0]||null};
}
